/* eslint-disable import/no-extraneous-dependencies */
import React, { useMemo } from 'react'

import { CodeIcon, GTMIcon } from 'public/static/redesign/integration';
import { Button, Spin } from 'antd';

import { InstructionContainer, MainContainer, CodeBlock, InstallationSection, StyledTabs, TabContent } from '../styles';
import { Code } from './MobileSDKIntegration';

function getCodeBlock(appKey: string) {
	return `
<script type="text/javascript" defer="">
(function( appKey, opts ) {
	window.uxc = {
		__t: [],
		__ak: appKey,
		__o: opts,
		event: function( n, p ) {
			this.__t.push( [ 'event', n, p ] )
		},
		setUserIdentity: function( i ) {
			this.__t.push( [ 'setUserIdentity', i ] )
		},
		setUserProperty: function( k, v ) {
			this.__t.push( [ 'setUserProperty', k, v ] )
		},
		setUserProperties: function( p ) {
			this.__t.push( [ 'setUserProperties', p ] )
		},
	};
	var head = document.getElementsByTagName('head')[0];
	var script = document.createElement('script');
	script.type = 'text/javascript';
	script.src = '//websdk-recording.uxcam.com/index.js';
	script.async = true;
	script.defer = true;
	script.id = 'uxcam-web-sdk';
	script.crossOrigin = 'anonymous';
	head.appendChild(script);
} )( '${appKey}', {} );
</script>
`;
}

const CodeTabContent: React.FC<{
	appKey: string,
	refreshedDesign?: boolean,
}> = ({
	appKey,
	refreshedDesign,
}) => {
		const codeBlock = React.useMemo(() => getCodeBlock(appKey), [appKey])
		return (
			<InstallationSection>
				<CodeBlock data-refreshed-design={refreshedDesign}>
					<span>{`Copy and paste the code snippet below on your website. We recommend adding it below your <head> tag.`}</span>
					<Code
						className='language-html'
					>
						{codeBlock}
					</Code>
					<a href="https://developer.uxcam.com/docs/installation" target="_blank" rel="noreferrer">
						Read UXCam integration guides  →
					</a>
				</CodeBlock>
			</InstallationSection>
		)
	}

const GTMTabContent: React.FC<{
	appKey: string,
	refreshedDesign?: boolean,
}> = ({
	appKey,
	refreshedDesign
}) => {
		const codeBlock = React.useMemo(() => getCodeBlock(appKey), [appKey])
		return (
			<InstallationSection>
				<CodeBlock data-refreshed-design={refreshedDesign}>
					<span>Copy and paste the code snippet below in a new custom HTML tag in Google Tag Manager and set it to fire on all pages.</span>
					<a href="https://support.google.com/tagmanager/answer/6107167?hl=en#CustomHTML" target="_blank" rel="noreferrer">
						How to create custom HTML tags in Google Tag Manager  →
					</a>
					<Code
						className='language-html'
					>
						{codeBlock}
					</Code>
					<i>Note: If you don’t have Google Tag Manager installed on your web environment, please refer to Google’s documentation.</i>
				</CodeBlock>
			</InstallationSection>
		)
	}
const WebSDKIntegration: React.FC<{
	appKey?: string,
	refreshedDesign?: boolean
}> = ({
	appKey = 'YOUR_APP_KEY',
	refreshedDesign
}) => {

		const [checkIntegrate, setCheckIntegrate] = React.useState(false);

		React.useEffect(() => {
			if (checkIntegrate) {
				const element = document.getElementById('web-info-card');
				if (element) {
					element.scrollIntoView({ behavior: 'smooth' });
				}
			}
		}, [checkIntegrate]);

		const CodeTab = useMemo(() => (
			<TabContent>
				<CodeIcon />
				Code
			</TabContent>
		), []);

		const GTMTab = useMemo(() => (
			<TabContent>
				<GTMIcon />
				Google Tag Manager
			</TabContent>
		), []);

		return (
			<MainContainer data-refreshed-design={refreshedDesign}>
				<InstructionContainer data-refreshed-design={refreshedDesign}>
					<p className='title'>{ refreshedDesign ? 'Choose your installation method:' : 'Choose your installation method for website: ' }</p>
					<StyledTabs data-refreshed-design={refreshedDesign}>
						<StyledTabs.TabPane tab={CodeTab} key="code">
							<CodeTabContent appKey={appKey} refreshedDesign={refreshedDesign} />
						</StyledTabs.TabPane>
						<StyledTabs.TabPane tab={GTMTab} key="gtm">
							<GTMTabContent appKey={appKey} refreshedDesign={refreshedDesign} />
						</StyledTabs.TabPane>
					</StyledTabs>
				</InstructionContainer>
				<Button className='integration-btn' type='primary' onClick={() => setCheckIntegrate(true)}>I&apos;ve finished initial integration</Button>
				{checkIntegrate && (
					<div className='info-card' id='web-info-card'>
						Once you add the tracking code and start receiving data, you will see sessions listed under &apos;Sessions page&apos;.
						<span className='info'>
							<Spin size='small' />
							Waiting to receive data
						</span>
					</div>
				)}
			</MainContainer>
		)
	}

export default React.memo(WebSDKIntegration)