const layoutStaticData = (isWebApp: boolean) => (
    {
        title: 'Get set up fast and unlock insights',
        subtitle: `Setting up UXCam on your ${isWebApp ? 'web' : 'mobile'} platform is easy and only takes a few minutes.`,
        appkeyText: 'You will need your UXCam app key:',
        sideInfo: "You don't have any data yet!",
        sideTitle: "Start Capturing Insights",
        sideSubtitle: 'Install UXCam to start auto-capturing data and sessions, analyzing user behavior, and getting insights.',
        sideTeammateCta: 'Send setup info to teammate',
        sideAssistanceTitle: 'Need assistance?',
        sideAssistanceSubtitle: "Discover how UXCam can elevate your user's experience",
        demoCta: 'Request demo',
        messageUs: 'Message us',
    }
)

export const copy = (e: React.MouseEvent) => {
    e.stopPropagation();
    e.preventDefault();
    message.success('Copied!');
};

const IntegrationLayout: React.FC<LayoutProps> = ({ isWebApp, appKey, children }) => {

    const {
        title,
        subtitle,
        appkeyText,
        sideInfo,
        sideTitle,
        sideSubtitle,
        sideTeammateCta,
        sideAssistanceSubtitle,
        sideAssistanceTitle,
        demoCta,
        messageUs } = layoutStaticData(isWebApp)

    const { profileReducer: profile } = useSelector((state: IReduxState) => state)

    const email = React.useMemo(() => encodeURIComponent(profile?.email), [profile])
    const nameParts = profile?.name?.split(' ') || [];
    const firstname = encodeURIComponent(nameParts[0]);
    const lastname = encodeURIComponent(nameParts.slice(1).join(' '));

    const [modalVisible, setModalVisible] = React.useState(false)

    const { CommonModal, openModal, setOpenModal } = useCommonModal()

    return (
        <Wrapper>
            <CommonModal
                title=''
                isModalOpen={openModal}
                hideButtons
                containerClassName='meeting-modal'
            >
                <ModalWrapper>
                    <button type='button' onClick={() => setOpenModal(false)}>
                        <CloseIcon />
                    </button>
                    <iframe
                        style={{
                            width: '100%',
                            height: '640px',
                            border: 'none',
                            margin: '0',
                            padding: '0',
                        }}
                        title="hubspot"
                        src={`https://info.uxcam.com/meetings/meet-uxcam/consultation?embed=true&email=${email}&firstname=${firstname}&lastname=${lastname}`}
                    />
                </ModalWrapper>
            </CommonModal>
            <EmailToDeveloperModalForm modalVisible={modalVisible} setModalVisible={setModalVisible} />
            <Main>
                <MainTop>
                    <h1>{title}</h1>
                    <p>{subtitle}</p>
                    {!isWebApp && <p>See the <a target='__blank' href='https://developer.uxcam.com/docs/so-what-does-uxcam-do'>integration docs</a> for more detailed guides.</p>}
                    <AppKeyWrapper>
                        <p>{appkeyText}</p><span>{appKey}<CopyToClipboard text={appKey}><button type='button' aria-label='Copy app key' onClick={(e) => copy(e)}><IconCopy /></button></CopyToClipboard></span>
                    </AppKeyWrapper>
                </MainTop>
                <Content>
                    {children}
                </Content>
            </Main>
            <Side>
                <SideInfo>
                    <IconInfo />
                    <h3>{sideInfo}</h3>
                </SideInfo>
                <SideTop>
                    <h2>{sideTitle}</h2>
                    <p>{sideSubtitle}</p>
                    <Button variant='primary' onClick={() => setModalVisible(true)}>
                        {sideTeammateCta}
                    </Button>
                </SideTop>
                <SideBottom>
                    <h2>{sideAssistanceTitle}</h2>
                    <p>{sideAssistanceSubtitle}</p>
                    <Button variant='primary' onClick={() => setOpenModal(true)}>
                        <IconCalendar />
                        {demoCta}
                    </Button>
                    <Button variant='ghost' onClick={() => showIntercom()}>
                        <IconMsg />
                        {messageUs}
                    </Button>
                </SideBottom>
            </Side>
        </Wrapper>
    )
}

export default memo(IntegrationLayout)