export const copy = (e: React.MouseEvent) => {
    e.stopPropagation();
    e.preventDefault();
    message.success('Copied!');
};

// eslint-disable-next-line @typescript-eslint/no-explicit-any
const BtnComp = (props: any) => {
    return (
        // eslint-disable-next-line react/jsx-props-no-spreading
        <SideButton {...props}>
            <IconArrow />
            Invite a teammate
        </SideButton>
    )
}

const TourIntegrationLayout: React.FC<LayoutProps> = ({ isWebApp, appKey, children }) => {
    const {
        profileReducer: profile,
        currentOrgReducer: { organizationName },
        currentAppReducer: { name: appName }
    } = useSelector((state: IReduxState) => state)
    const dispatch = useDispatch()

    const email = React.useMemo(() => encodeURIComponent(profile?.email), [profile])
    const nameParts = profile?.name?.split(' ') || [];
    const firstname = encodeURIComponent(nameParts[0]);
    const lastname = encodeURIComponent(nameParts.slice(1).join(' '));

    const [modalVisible, setModalVisible] = React.useState(false)

    const { CommonModal, openModal, setOpenModal } = useCommonModal()

    const handleShowAppKey = useCallback(() => {
        dispatch(trackPageViews(null, {
            eventName: 'wa_showing_app_key_integration_page',
            track_type: 'event',
            eventProperty: {
                orgName: organizationName,
                appName,
            },
        }))
    }, [dispatch, organizationName, appName])

    const handleCopyAppKey = useCallback(() => {
        dispatch(trackPageViews(null, {
            eventName: 'wa_copying_app_key_top_bar_integration_page',
            track_type: 'event',
            eventProperty: {
                orgName: organizationName,
                appName,
            },
        }))
    }, [dispatch, organizationName, appName])

    return (
        <Container>
            <CommonModal
                title=''
                isModalOpen={openModal}
                hideButtons
                containerClassName='meeting-modal'
            >
                <ModalWrapper>
                    <button type='button' onClick={() => setOpenModal(false)}>
                        <CloseIcon />
                    </button>
                    <iframe
                        style={{
                            width: '100%',
                            height: '640px',
                            border: 'none',
                            margin: '0',
                            padding: '0',
                        }}
                        title="hubspot"
                        src={`https://info.uxcam.com/meetings/meet-uxcam/consultation?embed=true&email=${email}&firstname=${firstname}&lastname=${lastname}`}
                    />
                </ModalWrapper>
            </CommonModal>
            <EmailToDeveloperModalForm modalVisible={modalVisible} setModalVisible={setModalVisible} />
            <Wrapper>
                <Main>
                    <MainTop>
                        <div>
                            <h1>Welcome {firstname}! You’re Almost Ready to Analyze!</h1>
                            <p>Connect your app and begin tracking sessions, events, and user behavior effortlessly.</p>
                        </div>
                        <AppKey
                            value={ appKey }
                            label="App key:"
                            onShowAppKey={ handleShowAppKey }
                            onCopyAppKey={ handleCopyAppKey }
                        />
                    </MainTop>
                    <Content>
                        {children}
                    </Content>
                </Main>
                <Side>
                    <MainSideTitle>
                        <SideTitle>
                            Need Help or Support?
                        </SideTitle>
                    </MainSideTitle>
                    <SideCard>
                        <IconsShare />
                        <SideTitle>
                           Hand off setup to your team
                        </SideTitle>
                        Invite a teammate so they can handle the integration and start capturing data.
                        <TeammateModalForm
                            hasTransferOwnership={undefined}
                            refetch={undefined}
                            selectedTeammate={undefined}
                            MainBtn={BtnComp}
                        />
                    </SideCard>
                    <SideCard>
                        <IconCalendar />
                        <SideTitle>
                            See UXCam in action
                        </SideTitle>
                        Request a demo with us and learn how you can elevate your digital analytics.
                        <SideButton onClick={() => setOpenModal(true)}>
                            <IconArrow />
                            Request a demo
                        </SideButton>
                        <SideButton onClick={() => showIntercom()}>
                            <IconArrow />
                            Message us
                        </SideButton>
                    </SideCard>
                    {!isWebApp && (
                        <SideCard>
                            <IconDoc />
                            <SideTitle>
                                Follow step‑by‑step guide
                            </SideTitle>
                            Read our integration docs to integrate UXCam on your platform
                            <SideLink href='https://developer.uxcam.com/docs/so-what-does-uxcam-do' target='_blank'>
                                <IconArrow />
                                Read integration docs
                            </SideLink>
                        </SideCard>
                    )}
                </Side>
            </Wrapper>
        </Container>
    )
}

export default memo(TourIntegrationLayout)