/* eslint-disable react/jsx-props-no-spreading */
import React, { useMemo } from 'react';
import {
  Alert,
  Button,
  Modal,
} from 'antd';
import {
  CheckCircleOutlined,
} from '@ant-design/icons';

import styled from 'styled-components';
import { useIsAppType } from 'hooks/useIsAppType';
import LockedPage from 'components/common/LockedPage';
import { useFeatureFlag, Spinner } from 'uxcam-frontend-components'
import MobileLocked from 'public/static/lock-features/mobile-locked-illustration.svg'
import { trackPageViews } from 'redux/actions/trackingReport';
import { useDispatch } from 'react-redux';
import WebLocked from 'public/static/lock-features/web-locked-illustration.svg'
import WebSDKIntegration from './IntegrationPages/WebSDKIntegration';
import IntegrationLayout from './IntegrationPages/IntegrationLayout';
import TourIntegrationLayout from './IntegrationPages/TourIntegrationLayout';
import EmailToDeveloperModalForm from './MailDeveloper';
import MobileSDKIntegration from './IntegrationPages/MobileSDKIntegration';
import { useRestrictionContext } from '../../context/restrictionContext';

const LoaderWrapper = styled.div`
  height: 100%;
  width: 100%;
`

const InfoDiv = styled.div`
  display: flex;
  justify-content: space-between;
  align-items: center;
  line-height: normal;
  font-family: 'Roboto';
  font-style: normal;
  .anticon {
    color: #f4584c;
    margin-right: 4px;
  }
`;

const StyledAlert = styled(Alert)`
  width: 100%;
  background: #fde9e7;
  border: none;
`;

const LockedWrapper = styled.div`
    height: calc(100% - 32px);
    width: calc(100% - 32px);
    margin: 16px;
    border: 1px solid #F3F4F5;
    border-radius: 6px;
`

export const InfoAlert = () => {
  const messageInfo = (
    <InfoDiv>
      <EmailToDeveloperModalForm buttonLabel="Send setup info to teammate" />
    </InfoDiv>
  );

  return (
    <StyledAlert message={messageInfo} />
  );
};

const WelcomePage = (props) => {
  const dispatch = useDispatch()
  const isWebAppSettingsEnabled = useIsAppType('web');
  const tourIntegration = useFeatureFlag('integration-with-tour', undefined, { undefinedWhenLoading: true })
  
  const { currentApp, successVisible, showMeMySession, _checkIntegrateDone: checkIntegrateDone, isWebDisabled, isMobileDisabled, planStatus } = props
  const { setShowPricingModal, selfServeFlag } = useRestrictionContext()

  const isCancelled = useMemo(() => planStatus === 'Canceled' || planStatus === 'Expired', [planStatus])

  const handleClickSeePricing = React.useCallback(() => {
    setShowPricingModal(true)
  }, [setShowPricingModal])

  const handleClickRequestPricing = React.useCallback(() => {
    setShowPricingModal(true)
  }, [setShowPricingModal])

  const isWebLocked = useMemo(() => !isCancelled && isWebAppSettingsEnabled && isWebDisabled, [isCancelled, isWebAppSettingsEnabled, isWebDisabled])
  const isMobileLocked = useMemo(() => !isCancelled && !isWebAppSettingsEnabled && isMobileDisabled, [isCancelled, isWebAppSettingsEnabled, isMobileDisabled])

  const eventSent = React.useRef(false)
  React.useEffect(() => {
    if (tourIntegration !== undefined && !eventSent.current) {
      dispatch(trackPageViews(undefined, {
        eventName: 'wa_ab_tour_integration_visit',
        extraPayload: {
          tourIntegrationFlag: tourIntegration,
        }
      }))
      eventSent.current = true
    }
  }, [dispatch, tourIntegration])

  if (isWebLocked) {
    return (
      <LockedWrapper>
        <LockedPage
          image={WebLocked}
          title="Get web analytics"
          subTitle="Optimize your web experience in UXCam"
          list={
            <>
              <li><strong>Real-time session replays:</strong> Dive into detailed session replays to see <br /> exactly how users navigate in your web</li>
              <li><strong>Best in class analytics:</strong> Built on the proven quality of UXCam&apos;s mobile <br /> analytics, now tailored for web</li>
              <li><strong>Shared Insights, Seamless Collaboration:</strong> Track web and mobile <br /> analytics in one tool, ensuring your team works together with unified <br /> data and insights.</li>
            </>
          }
          selfServeFlag={selfServeFlag}
          handleClickSeePricing={handleClickSeePricing}
          handleClickRequestPricing={handleClickRequestPricing}
          learnMoreLink='https://intercom.help/uxcamhelp/en/articles/10632047-intro-to-uxcam-for-web'
          dataIntercomTarget='Request-Web-Trial'
          openIntercom
        />
      </LockedWrapper>
    )
  }

  if (isMobileLocked) {
    return (
      <LockedWrapper>
        <LockedPage
          image={MobileLocked}
          title="Get mobile analytics"
          subTitle="Optimize your mobile experience in UXCam"
          list={
            <>
              <li><strong>Real-time session replays:</strong> Dive into detailed session replays to see <br /> exactly how users navigate in your mobile app</li>
              <li><strong>Best in class analytics:</strong> Best mobile SDK on the market.</li>
              <li><strong>Shared Insights, Seamless Collaboration:</strong> Track web and mobile <br /> analytics in one tool, ensuring your team works together with unified <br /> data and insights.</li>
            </>
          }
          selfServeFlag={selfServeFlag}
          handleClickSeePricing={handleClickSeePricing}
          handleClickRequestPricing={handleClickRequestPricing}
          learnMoreLink='https://intercom.help/uxcamhelp/en/collections/11057111-product-analytics-features'
          dataIntercomTarget="Request-Mobile-Trial"
          openIntercom
        />
      </LockedWrapper>
    )
  }

  if (tourIntegration === undefined) {
    return (
      <LoaderWrapper>
        <Spinner data-size="m" />
      </LoaderWrapper>
    )
  }

  if (!tourIntegration) {
    return (
      <IntegrationLayout isWebApp={isWebAppSettingsEnabled} appKey={currentApp?.key}>
        {
          isWebAppSettingsEnabled ? (
            <WebSDKIntegration
              appKey={props?.currentApp?.key}
              checkIntegrateDone={checkIntegrateDone}
            />
          ) : (
            <MobileSDKIntegration {...props} />
          )
        }
        <Modal
          visible={successVisible}
          onOk={showMeMySession}
          className="success-modal"
          footer={[
            <Button
              key="submit"
              type="primary"
              size="large"
              onClick={showMeMySession}
            >
              Show me my sessions
            </Button>,
          ]}
        >
          <div className="success-sdk">
            <CheckCircleOutlined />
            <h3 style={{ color: '#46B34A' }}>Congratulations</h3>
            <p>The tracking code has been installed successfully on your {isWebAppSettingsEnabled ? 'web' : 'mobile app'} and data is being received.</p>
          </div>
        </Modal>
      </IntegrationLayout>
    )
  }

  return (
    <TourIntegrationLayout isWebApp={isWebAppSettingsEnabled} appKey={currentApp?.key}>
      {
        isWebAppSettingsEnabled ? (
          <WebSDKIntegration
            appKey={props?.currentApp?.key}
            checkIntegrateDone={checkIntegrateDone}
            refreshedDesign
          />
        ) : (
          <MobileSDKIntegration 
            refreshedDesign
            {...props}
          />
        )
      }
      <Modal
        visible={successVisible}
        onOk={showMeMySession}
        className="success-modal"
        footer={[
          <Button
            key="submit"
            type="primary"
            size="large"
            onClick={showMeMySession}
          >
            Show me my sessions
          </Button>,
        ]}
      >
        <div className="success-sdk">
          <CheckCircleOutlined />
          <h3 style={{ color: '#46B34A' }}>Congratulations</h3>
          <p>The tracking code has been installed successfully on your {isWebAppSettingsEnabled ? 'web' : 'mobile app'} and data is being received.</p>
        </div>
      </Modal>
    </TourIntegrationLayout>
  )
};

export default WelcomePage;
