import React, { useState, useRef, useEffect } from 'react';
import { Button, Modal, Form, Input, message } from 'antd';
import styled from 'styled-components';
import { useDispatch, useSelector } from 'react-redux';
import { useMutation } from 'react-query';
import ReactHtmlParser from 'react-html-parser';

import { changeCommonValue } from 'redux/actions/common';
import { emailValidateRule } from 'Utils/helpers/EmailValidateRule';
import SettingApi from 'services/settingApi';
import ForbiddenModal from 'components/features/setting/OrganizationSetting/TeamSection/ForbiddenModal';
import { useIsAppType } from 'hooks/useIsAppType';

const ModalWrap = styled(Modal)`
  .ant-modal-content {
    padding: 20px;
    border-radius: 8px;
  }
  .ant-modal-body {
    padding: 8px;
  }
  .ant-modal-footer {
    display: none;
  }
`;

const EditModalWrap = styled.div`
  .ant-select-dropdown {
    border-radius: 8px;
    padding: 20px;
  }
  .ant-select:not(.ant-select-customize-input) .ant-select-selector {
    border: none;
  }
  .ant-select-item-option {
    padding: 10px 20px;
  }
`;

const ModalHeaderWrap = styled.div`
  display: flex;
  justify-content: space-between;
  margin-bottom: 15px;
`;

const TextTitle = styled.div`
  font-size: 18px;
  font-weight: 500;
`;

const InputWrap = styled(Input)`
  margin: 10px 0;
  border: auto;
`;

const PrimaryModalButton = styled(Button)`
  border-radius: 4px;
  color: #ffffff;
  font-size: 14px;
  margin-top: 10px;
  padding: 0 30px;
`;

const SecondaryModalButton = styled(PrimaryModalButton)`
  background: #ffffff;
  color: #5d97ff;
  border: 1px solid #5d97ff;
  margin-right: 15px;
  height: 36px;
`;

const FormButton = styled.div`
  display: flex;
  justify-content: end;
`;

const FormItem = Form.Item;

const EmailToDeveloperModalForm = ({
  modalVisible, setModalVisible,
}) => {
  const dispatch = useDispatch();
  const [form] = Form.useForm();

  const [visibleForbiddenModal, setVisibleForbiddenModal] = useState(false);
  const inputRef = useRef(null);

  const isWebSDK = useIsAppType( 'web' );

  const {
    currentOrgReducer: { orgId },
    urlReducer: { appId },
  } = useSelector((state) => state);

  const { mutate: emailTeammate, isLoading } = useMutation(
    SettingApi.emailToTeammates,
    {
      onSuccess: (response) => {
        message.success(
          response?.data?.message || 'Setup info send successfully.'
        );
        setModalVisible(false);
      },
      onError: (error) => {
        if (error?.response?.status === 403) {
          setModalVisible(false);
          setVisibleForbiddenModal(true);
        } else if (
          error?.response?.data?.error?.message?.includes(
            'upgrade your account'
          )
        ) {
          dispatch(
            changeCommonValue(
              'isVisible_custom_popup',
              true,
              ReactHtmlParser(error?.response?.data?.error?.message)
            )
          );
          setModalVisible(false);
        } else {
          const errorResponse =
            error?.response?.data?.error?.email?.[0] ||
            error?.response?.data?.error?.message ||
            'Send setup info failed.';
          message.error(errorResponse);
        }
      },
    }
  );

  const handleDestroyClose = () => {
    form.resetFields();
  };

  const onFinish = (values) => {
    const payload = {
      data: {
        ...values,
        isWebSDK,
      },
      orgId,
    };

    emailTeammate(payload);
  
  };

  const handleCancel = async () => {
    setModalVisible(false);
  };

  useEffect(() => {
    const inputFocus = setTimeout(() => {
      modalVisible && inputRef?.current && inputRef?.current.focus();
    }, 500);
    return () => {
      clearTimeout(inputFocus);
    };
  }, [modalVisible, inputRef]);

  return (
    <>
      <ModalWrap
        visible={modalVisible}
        onCancel={handleCancel}
        closable={false}
        afterClose={handleDestroyClose}
        footer={[]}
        maskClosable={false}
        destroyOnClose
      >
        <Form form={form} onFinish={onFinish} requiredMark={false}>
          <EditModalWrap>
            <ModalHeaderWrap>
              <TextTitle>Send setup info to teammate</TextTitle>
            </ModalHeaderWrap>
            <FormItem noStyle name="appId" initialValue={appId} />

            <FormItem
              name="email"
              rules={[
                {
                  required: true,
                  whitespace: true,
                  message: 'Please input email.',
                },
                { validator: emailValidateRule },
              ]}
            >
              <InputWrap placeholder="Enter email address" ref={inputRef} />
            </FormItem>
          </EditModalWrap>
          <FormButton>
            <SecondaryModalButton
              key="link"
              type="secondary"
              onClick={() => handleCancel()}
            >
              Cancel
            </SecondaryModalButton>

            <PrimaryModalButton
              key="submit"
              htmlType="submit"
              type="primary"
              loading={isLoading}
            >
              Send
            </PrimaryModalButton>
          </FormButton>
        </Form>
      </ModalWrap>

      {visibleForbiddenModal && (
        <ForbiddenModal
          visibleForbiddenModal={visibleForbiddenModal}
          setVisibleForbiddenModal={setVisibleForbiddenModal}
        />
      )}
    </>
  );
};

export default EmailToDeveloperModalForm;
