const { TabPane } = Tabs;

const initialTabStates = {
  primary: null,
  secondary: null,
  tertiary: null,
}

function reducer(state: any, action: any) {
  switch (action.type) {
    case 'primary':
      return { ...initialTabStates, primary: action.payload };
    case 'secondary':
      return { ...state, secondary: action.payload };
    case 'tertiary':
      return { ...state, tertiary: action.payload };
    default:
      return state;
  }
}

