// Wrapper component to intercept copy events from CodeCopy
const CodeCopyWrapper = ({ children, onCopyCallback, ...props }: any) => {
  const wrapperRef = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    const handleCopy = () => {
      if (onCopyCallback) {
        onCopyCallback();
      }
    };

    const wrapper = wrapperRef.current;
    if (wrapper && onCopyCallback) {
      // Listen for clicks on the copy button
      const handleClick = (e: MouseEvent) => {
        const target = e.target as HTMLElement;
        // Check if the clicked element is the copy button
        if (target.closest('button[aria-label*="Copy"]') || target.closest('button[aria-label*="Copied"]')) {
          handleCopy();
        }
      };

      wrapper.addEventListener('click', handleClick);
      return () => {
        wrapper.removeEventListener('click', handleClick);
      };
    }

    return undefined;
  }, [onCopyCallback]);

  return (
    <div ref={wrapperRef}>
      <CodeCopy {...props}>{children}</CodeCopy>
    </div>
  );
};

export const Code = (props: any) => {
  const { theme: codeTheme, suffixContent, onCopy, ...rest } = props;
  return (
    <CodeCopyWrapper theme={codeTheme} text={props.children} onCopyCallback={onCopy}>
      <PreCode {...rest} />
      {suffixContent && (
        <SuffixContent>
          {suffixContent}
        </SuffixContent>
      )}
    </CodeCopyWrapper>
  );
};

